import sys
from collections import defaultdict, deque

def bfs(graph, start):
    visited = set()
    queue = deque([start])
    visited.add(start)
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return visited

n, m = map(int, sys.stdin.readline().split())
edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]
q = int(sys.stdin.readline())
queries = [tuple(map(int, sys.stdin.readline().split())) for _ in(range(q))]

color_graphs = defaultdict(lambda: defaultdict(list))
for a, b, c in edges:
    color_graphs[c][a].append(b)
    color_graphs[c][b].append(a)

results = []
for u, v in queries:
    count = 0
    for color, graph in color_graphs.items():
        if u in graph and v in graph:
            connected = bfs(graph, u)
            if v in connected:
                count += 1
    results.append(count)

for result in results:
    print(result)
